%% |sub-questions are handed to Result.new as the model gave them| — laws/decomposition_llm.lawspec:214
%% When the model replies with sub_questions and does not say atomic:
%%     true, the decomposition is Result.new of the question and that list,
%%     unchanged: flat, one dependency-free entry per sub-question, in the
%%     model's order. Nothing is trimmed, dropped or merged, so a blank
%%     sub-question and a repeated one are entries like any other.
%% for all (question :: Text) (subQuestions :: List (Text)) (deniesAtomic :: Bool) => modelSaysJson (subQuestionJson deniesAtomic subQuestions) = true and llmDecompose question (Maybe::Absent()) = Either::Right(resultNew question subQuestions) end for all
