    Schema,
    Symbols,
    [Question, SubQuestions, DeniesAtomic]
) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says_json(
            Schema,
            Symbols,
            lawspec_definitions:sub_question_json(Schema, Symbols, DeniesAtomic, SubQuestions)
        ),
        true,
        ?LAW_SUB_QUESTIONS_ARE_HANDED_TO_RESULT_NEW_AS_THE
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:llm_decompose(Schema, Symbols, Question, make_absent([], Schema)),
            make_right(
