%% |an empty list of sub-questions is the atomic decomposition| — laws/decomposition_llm.lawspec:273
%% A reply whose sub_questions list is empty collapses to the atomic
%%     decomposition: the same result as atomic: true, with strategy none.
%% for all (question :: Text) (deniesAtomic :: Bool) => modelSaysJson (subQuestionJson deniesAtomic (List::Nil())) = true and llmDecompose question (Maybe::Absent()) = Either::Right(atomicOf question) end for all
law_an_empty_list_of_sub_questions_is_the_atomic(Schema, Symbols, [Question, DeniesAtomic]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says_json(
            Schema,
            Symbols,
            lawspec_definitions:sub_question_json(Schema, Symbols, DeniesAtomic, [])
        ),
        true,
        ?LAW_AN_EMPTY_LIST_OF_SUB_QUESTIONS_IS_THE_ATOMIC
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:llm_decompose(Schema, Symbols, Question, make_absent([], Schema)),
            make_right([lawspec_definitions:atomic_of(Schema, Symbols, Question)], Schema),
            ?LAW_AN_EMPTY_LIST_OF_SUB_QUESTIONS_IS_THE_ATOMIC
        )).

