%% |a reply with neither answer is an invalid response| — laws/decomposition_llm.lawspec:314
%% A reply that fits the schema but gives no sub-questions and does not
%%     say atomic: true (the empty object, or atomic: false alone) is an
%%     invalid-response failure.
%% for all (question :: Text) (deniesAtomic :: Bool) => modelSaysJson (neitherJson deniesAtomic) = true and isInvalidResponse (llmDecompose question (Maybe::Absent())) = true end for all
law_a_reply_with_neither_answer_is_an_invalid(Schema, Symbols, [Question, DeniesAtomic]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says_json(
            Schema,
            Symbols,
            lawspec_definitions:neither_json(Schema, Symbols, DeniesAtomic)
