        true,
        ?LAW_A_REPLY_WITH_NEITHER_ANSWER_IS_AN_INVALID
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:is_invalid_response(
                Schema,
                Symbols,
                lawspec_definitions:llm_decompose(
                    Schema,
                    Symbols,
                    Question,
                    make_absent([], Schema)
                )
            ),
            true,
            ?LAW_A_REPLY_WITH_NEITHER_ANSWER_IS_AN_INVALID
