-define(LAW_EVERY_REPLY_THAT_FITS_THE_SCHEMA_IS_ANSWERED,
    <<"cake.laws.decomposition_llm::|every reply that fits the schema is answered|">>
).

%% |every reply that fits the schema is answered| — laws/decomposition_llm.lawspec:340
%% Whatever JSON the decomposition schema admits, decompose returns a
%%     decomposition or an invalid-response failure. It never raises, and it
%%     never reports a reply it could not read as a generation failure. The
%%     laws above say which of the two each reply gets.
%% for all (question :: Text) (json :: cake.laws.generation::type::DecompositionJson) => modelSaysJson json = true and wasRead (llmDecompose question (Maybe::Absent())) = true end for all
law_every_reply_that_fits_the_schema_is_answered(Schema, Symbols, [Question, Json]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says_json(Schema, Symbols, Json),
        true,
        ?LAW_EVERY_REPLY_THAT_FITS_THE_SCHEMA_IS_ANSWERED
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:was_read(
                Schema,
                Symbols,
                lawspec_definitions:llm_decompose(
                    Schema,
                    Symbols,
                    Question,
                    make_absent([], Schema)
                )
            ),
            true,
            ?LAW_EVERY_REPLY_THAT_FITS_THE_SCHEMA_IS_ANSWERED
        )).

law_every_reply_that_fits_the_schema_is_answered_case(BaseSchema, Symbols, Values) ->
