-define(LAW_A_GENERATION_FAILURE_COMES_BACK_AS_A_GENERATION,
    <<"cake.laws.decomposition_llm::|a generation failure comes back as a generation error|">>
).

%% |a generation failure comes back as a generation error| — laws/decomposition_llm.lawspec:356
%% When the generation module fails, decompose fails with a generation
%%     error that carries exactly that failure.
%% for all (question :: Text) (error :: cake.laws.generation::type::GenerationError) => modelSays (cake.laws.generation::type::Reply::Errors(error)) = true and llmDecompose question (Maybe::Absent()) = Either::Left(cake.laws.decomposition_llm::type::DecompositionError::GenerationFailed(error)) end for all
law_a_generation_failure_comes_back_as_a_generation(Schema, Symbols, [Question, Error]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says(Schema, Symbols, make_errors([Error], Schema)),
        true,
        ?LAW_A_GENERATION_FAILURE_COMES_BACK_AS_A_GENERATION
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:llm_decompose(Schema, Symbols, Question, make_absent([], Schema)),
            make_left([make_generation_failed([Error], Schema)], Schema),
            ?LAW_A_GENERATION_FAILURE_COMES_BACK_AS_A_GENERATION
        )).

