%% |a generation failure comes back as a generation error| example |a rejected key| — laws/decomposition_llm.lawspec:370
law_a_generation_failure_comes_back_as_a_generation__a_rejected_key() ->
    {Schema, Symbols} = lawspec_data:context(),
    lawspec_beam_effects:with_scope(
        Schema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.decomposition_llm::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.decomposition_llm::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end
        },
        fun(ExampleSchema) ->
            Question = <<"How does the RO-400 filter compare to the RO-500?">>,
            Error = make_auth([<<"Incorrect API key provided">>], ExampleSchema),
            lawspec_beam_runtime:require(
                law_a_generation_failure_comes_back_as_a_generation(
                    ExampleSchema,
                    Symbols,
                    [Question, Error]
                ),
                ?LAW_A_GENERATION_FAILURE_COMES_BACK_AS_A_GENERATION
            ),
            lawspec_beam_runtime:assert_equal(
                (lawspec_definitions:model_says(
                    ExampleSchema,
                    Symbols,
                    make_errors([Error], ExampleSchema)
                ) andalso
                    lawspec_beam_scalar:equal(
                        lawspec_definitions:llm_decompose(
                            ExampleSchema,
                            Symbols,
                            Question,
                            make_absent([], ExampleSchema)
                        ),
                        make_left(
                            [
                                make_generation_failed(
                                    [make_auth([<<"Incorrect API key provided">>], ExampleSchema)],
                                    ExampleSchema
                                )
                            ],
                            ExampleSchema
                        )
                    )),
                true,
                <<"|a generation failure comes back as a generation error| example |a rejected key| — laws/decomposition_llm.lawspec:370"/utf8>>
            )
        end
    ).

