-define(LAW_THE_ORIGINAL_QUESTION_IS_KEPT,
    <<"cake.laws.decomposition_llm::|the original question is kept|">>
).

%% |the original question is kept| — laws/decomposition_llm.lawspec:376
%% A decomposition carries the question decompose was asked, unchanged,
%%     whatever the model replied.
%% for all (question :: Text) (said :: cake.laws.decomposition_llm::type::Said) => modelSays (replyOf said) = true and keepsQuestion question (llmDecompose question (Maybe::Absent())) = true end for all
law_the_original_question_is_kept(Schema, Symbols, [Question, Said]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says(
            Schema,
            Symbols,
            lawspec_definitions:reply_of(Schema, Symbols, Said)
        ),
        true,
        ?LAW_THE_ORIGINAL_QUESTION_IS_KEPT
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:keeps_question(
                Schema,
                Symbols,
                Question,
                lawspec_definitions:llm_decompose(
                    Schema,
                    Symbols,
                    Question,
                    make_absent([], Schema)
                )
            ),
            true,
            ?LAW_THE_ORIGINAL_QUESTION_IS_KEPT
        )).

law_the_original_question_is_kept_case(BaseSchema, Symbols, Values) ->
    lawspec_beam_effects:with_scope(
        BaseSchema,
        #{
            <<"cake.laws.generation::ability::Generation">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.decomposition_llm::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
                )
            end,
            <<"cake.laws.generation::ability::Provider">> => fun(_FactorySchema) ->
                lawspec_beam_effects:shared(
                    _FactorySchema,
                    <<"cake.laws.decomposition_llm::handler::scripted">>,
                    fun() -> lawspec_abilities:scripted(_FactorySchema, Symbols) end
