-define(LAW_THE_STRATEGY_IS_NEVER_SEQUENTIAL_SELF_ASK_OR,
    <<"cake.laws.decomposition_llm::|the strategy is never sequential, self-ask or IRCoT|">>
).

%% |the strategy is never sequential, self-ask or IRCoT| — laws/decomposition_llm.lawspec:389
%% Whatever the model replies, a decomposition from decompose is atomic
%%     or flat. The schema has no way to state a dependency between
%%     sub-questions, and decompose never marks a result self-ask or IRCoT.
%% for all (question :: Text) (said :: cake.laws.decomposition_llm::type::Said) => modelSays (replyOf said) = true and atomicOrFlat (llmDecompose question (Maybe::Absent())) = true end for all
law_the_strategy_is_never_sequential_self_ask_or(Schema, Symbols, [Question, Said]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says(
            Schema,
            Symbols,
            lawspec_definitions:reply_of(Schema, Symbols, Said)
        ),
        true,
        ?LAW_THE_STRATEGY_IS_NEVER_SEQUENTIAL_SELF_ASK_OR
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:atomic_or_flat(
                Schema,
                Symbols,
                lawspec_definitions:llm_decompose(
                    Schema,
                    Symbols,
                    Question,
                    make_absent([], Schema)
                )
            ),
            true,
            ?LAW_THE_STRATEGY_IS_NEVER_SEQUENTIAL_SELF_ASK_OR
        )).

