-define(LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE,
    <<"cake.laws.decomposition_llm::|decompose asks the generation module once|">>
).

%% |decompose asks the generation module once| — laws/decomposition_llm.lawspec:402
%% Whatever the model replies, decompose makes exactly one request: a
%%     complete_json of the decomposition prompt for the question, to the
%%     model it was given (gpt-4o-mini when it was given none), with the
%%     decomposition schema. It never calls complete, and it does not ask
%%     again after a failure.
%% for all (question :: Text) (model :: Maybe (Text)) (said :: cake.laws.decomposition_llm::type::Said) => modelSays (replyOf said) = true and answered (llmDecompose question model) = true and calls of completeJson with (decompositionPrompt question, modelAsked model, cake.laws.generation::type::Schema::DecompositionSchema()) = 1 and calls of completeJson = 1 and calls of complete = 0 end for all
law_decompose_asks_the_generation_module_once(Schema, Symbols, [Question, Model, Said]) ->
    ((((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:model_says(
            Schema,
            Symbols,
            lawspec_definitions:reply_of(Schema, Symbols, Said)
        ),
        true,
        ?LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:answered(
                Schema,
                Symbols,
                lawspec_definitions:llm_decompose(Schema, Symbols, Question, Model)
            ),
            true,
            ?LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_effects:count_calls(
                Schema,
                <<"cake.laws.generation::ability::Generation">>,
                <<"completeJson">>,
                [
                    lawspec_definitions:decomposition_prompt(Schema, Symbols, Question),
                    lawspec_definitions:model_asked(Schema, Symbols, Model),
                    make_decomposition_schema([], Schema)
                ]
            ),
            1,
            ?LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_effects:count_calls(
                Schema,
                <<"cake.laws.generation::ability::Generation">>,
                <<"completeJson">>,
                any
            ),
            1,
            ?LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_effects:count_calls(
                Schema,
                <<"cake.laws.generation::ability::Generation">>,
                <<"complete">>,
                any
            ),
            0,
            ?LAW_DECOMPOSE_ASKS_THE_GENERATION_MODULE_ONCE
        )).

law_decompose_asks_the_generation_module_once_case(BaseSchema, Symbols, Values) ->
    lawspec_beam_effects:with_scope(
